```typescript
export interface OverlayRunConfig {
  limit?: number;            // default: 5
  status_filter?: string;    // 'approved' | 'draft' (default: 'draft' for testing)
  clips_dir?: string;        // default: ~/kognai/clips
  final_dir?: string;        // default: ~/kognai/final
  dry_run?: boolean;
}

export interface OverlayRunResult {
  processed: number;
  overlays_applied: number;
  stored: number;
  errors: string[];
  duration_ms: number;
}

export async function runOverlay(config: OverlayRunConfig): Promise<OverlayRunResult>;
```

Pipeline:
1. Query tiktok_briefs: status = status_filter, clip_status IN ('ready','pending'), final_path IS NULL, ORDER BY score DESC LIMIT limit
   - Note: use 'pending' too so dry-run clips (never DB-updated) are included in testing
2. For each brief:
   a. clipPath = path.join(clips_dir, `{brief.id}.mp4`)
   b. If clip doesn't exist on disk → skip with warning
   c. finalPath = path.join(final_dir, `{brief.id}.mp4`)
   d. applyTextOverlay(clipPath, finalPath, { hookText: brief.hook })
   e. Log: `[overlay] [T03] "Soviet scientists..." → final/abc123.mp4`
   f. If !dry_run: UPDATE tiktok_briefs SET final_path = finalPath WHERE id = brief.id
3. Return OverlayRunResult

Entry point (add --draft and --dry-run flags to existing clip-runner package.json scripts):
```typescript
if (import.meta.url === `file://${process.argv[1]}`) {
  const isDryRun = process.argv.includes('--dry-run');
  const isDraft = process.argv.includes('--draft');
  runOverlay({
    limit: 5,
    status_filter: isDraft ? 'draft' : 'approved',
    dry_run: isDryRun,
  }).then(r => {
    console.log(`\n=== DONE: ${r.overlays_applied} overlays, ${r.stored} stored ===`);
    if (r.errors.length) console.log('Errors:', r.errors);
  }).catch(err => { console.error('Fatal:', err); process.exit(1); });
}
```

